def stamp(ts: int) -> str:
    """Format a Unix timestamp in seconds as HH:MM:SS.

    The time is UTC, uses the 24-hour clock, and is zero padded.
    The result wraps every 86400 seconds, so stamp(86400) == "00:00:00".
    Negative values floor toward earlier times, so stamp(-1) == "23:59:59".
    """
    s = ts % 86400
    hours, rem = divmod(s, 3600)
    minutes, seconds = divmod(rem, 60)
    return f"{hours:02d}:{minutes:02d}:{seconds:02d}"


def test_stamp_midnight() -> None:
    assert stamp(0) == "00:00:00"


def test_stamp_small_values_are_zero_padded() -> None:
    assert stamp(3661) == "01:01:01"


def test_stamp_afternoon() -> None:
    assert stamp(45296) == "12:34:56"


def test_stamp_last_second_of_day() -> None:
    assert stamp(86399) == "23:59:59"


def test_stamp_wraps_at_day_boundary() -> None:
    assert stamp(86400) == "00:00:00"
    assert stamp(86400 + 3661) == "01:01:01"


def test_stamp_negative_floors_to_previous_day() -> None:
    assert stamp(-1) == "23:59:59"
